package app.sketchsolve.data

/** A formula: name, equation in formula style, and what each letter means. */
data class Formula(val id: String, val cat: String, val name: String, val eq: String, val vars: List<FVar>, val note: String? = null)
data class FVar(val name: String, val desc: String, val unit: String, val default: Double? = null)
data class Category(val id: String, val name: String, val icon: String)

